-- Atomic publication; concurrent editors cannot overwrite each other.
BEGIN;
CREATE TABLE IF NOT EXISTS public.home_content (
  tab_key text PRIMARY KEY CHECK (tab_key IN ('grocery', 'fresh', 'regional')),
  home_tab_id uuid UNIQUE REFERENCES public.home_tabs(id) ON DELETE SET NULL,
  content jsonb NOT NULL CHECK (jsonb_typeof(content) = 'object' AND content->>'schemaVersion' = '1' AND jsonb_typeof(content->'sections') = 'array' AND octet_length(content::text) <= 262144),
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS public.home_content_history (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tab_key text NOT NULL,
  revision integer NOT NULL,
  content jsonb NOT NULL,
  changed_at timestamptz NOT NULL DEFAULT now(),
  changed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  UNIQUE (tab_key, revision)
);
ALTER TABLE public.home_content ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.home_content_history ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS home_content_public_read ON public.home_content;
CREATE POLICY home_content_public_read ON public.home_content FOR SELECT TO anon, authenticated USING (true);
REVOKE ALL ON public.home_content, public.home_content_history FROM anon, authenticated;
GRANT SELECT (tab_key, home_tab_id, content, revision, updated_at) ON public.home_content TO anon, authenticated;
GRANT ALL ON public.home_content, public.home_content_history TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.home_content_history_id_seq TO service_role;
CREATE OR REPLACE FUNCTION public.revise_home_content() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  NEW.revision := OLD.revision + 1;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;
CREATE OR REPLACE FUNCTION public.audit_home_content() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  INSERT INTO public.home_content_history(tab_key, revision, content, changed_by)
  VALUES (NEW.tab_key, NEW.revision, NEW.content, NEW.updated_by);
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS home_content_revision ON public.home_content;
CREATE TRIGGER home_content_revision BEFORE UPDATE ON public.home_content FOR EACH ROW EXECUTE FUNCTION public.revise_home_content();
DROP TRIGGER IF EXISTS home_content_audit ON public.home_content;
CREATE TRIGGER home_content_audit AFTER INSERT OR UPDATE ON public.home_content FOR EACH ROW EXECUTE FUNCTION public.audit_home_content();
-- Keep existing Home Categories controls consistent with the new editor.
-- Difference guards stop recursive triggers and unnecessary revisions.
CREATE OR REPLACE FUNCTION public.sync_content_to_home_tab() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  UPDATE public.home_tabs SET name = NEW.content->>'tabTitle', is_active = (NEW.content->>'enabled')::boolean
  WHERE id = NEW.home_tab_id AND (name IS DISTINCT FROM NEW.content->>'tabTitle' OR is_active IS DISTINCT FROM (NEW.content->>'enabled')::boolean);
  RETURN NEW;
END;
$$;
CREATE OR REPLACE FUNCTION public.sync_home_tab_to_content() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.home_content WHERE home_tab_id = NEW.id) AND (length(trim(NEW.name)) = 0 OR length(NEW.name) > 32) THEN
    RAISE EXCEPTION 'Managed Home tab titles must contain 1 to 32 characters.' USING ERRCODE = '23514';
  END IF;
  UPDATE public.home_content SET updated_by = auth.uid(), content = jsonb_set(jsonb_set(content, '{tabTitle}', to_jsonb(NEW.name)), '{enabled}', to_jsonb(NEW.is_active))
  WHERE home_tab_id = NEW.id AND (content->>'tabTitle' IS DISTINCT FROM NEW.name OR (content->>'enabled')::boolean IS DISTINCT FROM NEW.is_active);
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS home_content_tab_sync ON public.home_content;
CREATE TRIGGER home_content_tab_sync AFTER INSERT OR UPDATE ON public.home_content FOR EACH ROW EXECUTE FUNCTION public.sync_content_to_home_tab();
DROP TRIGGER IF EXISTS home_tab_content_sync ON public.home_tabs;
CREATE TRIGGER home_tab_content_sync AFTER UPDATE OF name, is_active ON public.home_tabs FOR EACH ROW EXECUTE FUNCTION public.sync_home_tab_to_content();
