ON CONFLICT (tab_key) DO NOTHING;
UPDATE public.home_content c SET home_tab_id = (
  SELECT t.id FROM public.home_tabs t WHERE lower(trim(t.name)) = ANY (
    CASE c.tab_key WHEN 'grocery' THEN ARRAY['grocery','groceries'] WHEN 'fresh' THEN ARRAY['fresh','fruit & veg','fruits & veg'] ELSE ARRAY['regional'] END
  ) ORDER BY t.sort_order LIMIT 1
) WHERE c.home_tab_id IS NULL;
DO $$
DECLARE table_name text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    FOREACH table_name IN ARRAY ARRAY['home_content', 'home_tabs', 'products', 'product_variants', 'stores'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = table_name) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', table_name);
      END IF;
    END LOOP;
  END IF;
END;
$$;
COMMIT;
